#!/bin/sh
# Exact visual loop generated from the uploaded 53-frame GIF.
# Requires a SIXEL-capable terminal and ImageMagick (magick or convert).
set -eu
TMP="$(mktemp -d 2>/dev/null || mktemp -d -t karanascii)"
trap 'rm -rf "$TMP"' EXIT INT TERM
GIF="$TMP/karan.gif"
base64 -d > "$GIF" <<'KARAN_GIF_BASE64'

KARAN_GIF_BASE64
if command -v magick >/dev/null 2>&1; then IM=magick
elif command -v convert >/dev/null 2>&1; then IM=convert
else
  echo "ImageMagick required: install 'imagemagick' first." >&2
  exit 1
fi

# 53 frames, 110 ms each, matching the uploaded GIF timing.
while :; do
  i=0
  while [ "$i" -lt 53 ]; do
    printf '[2J[H'
    "$IM" "$GIF[$i]" sixel:-
    sleep 0.11
    i=$((i + 1))
  done
done
